(()=>{
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)],config=window.STORE_CONFIG;let quantity=2,mode="subscription";
function message(text){$('.template-message')?.remove();const box=document.createElement('div');box.className='template-message';box.role='status';box.textContent=text;document.body.append(box);setTimeout(()=>box.remove(),6500);}
function selected(){return mode==='subscription'?config.subscription:config.offers[quantity];}
function purchasable(){const o=selected();return Boolean(o&&o.price>0&&config.currency&&/^https:\/\//.test(o.checkoutUrl));}
function prices(){const o=selected();const n=mode==='subscription'?1:quantity;const ready=purchasable();$('[data-add-to-cart]').disabled=!ready;$('[data-add-to-cart-text]').textContent=ready?(mode==='subscription'?'Start AutoShip':'Get my bundle'):'Checkout coming soon';$('[data-pack-copy]').textContent=n+'  x  140 mL '+(n===1?'bottle with included spatula':'bottles with included spatulas');$('[data-order-summary]').textContent=mode==='subscription'?'$24 every 30 days  |  Free shipping  |  Cancel anytime':'Total $'+(o.price+o.shipping).toFixed(2)+(o.shipping?' including $5.95 shipping':'  |  Free shipping');}
$$('[data-purchase-option]').forEach(input=>input.addEventListener('change',()=>{quantity=Number(input.value);prices();}));
$$('[data-purchase-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.purchaseMode;$$('[data-purchase-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('[data-subscription-offer]').hidden=mode!=='subscription';$('[data-bundle-offers]').hidden=mode!=='bundle';prices();}));prices();
$$('form:not([data-offer-claim])').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(form.hasAttribute('data-buybox-form')&&purchasable()){location.assign(selected().checkoutUrl);return;}message('AERASE checkout is being prepared.');}));
$$('[data-trigger]').forEach(button=>{const panel=document.getElementById(button.getAttribute('aria-controls'));if(!panel)return;function toggle(open){button.setAttribute('aria-expanded',String(open));panel.hidden=!open;}toggle(button.getAttribute('aria-expanded')==='true');button.addEventListener('click',()=>toggle(button.getAttribute('aria-expanded')!=='true'));});
const slides=$$('[data-gallery-slide]');const slideParent=slides[0]?.parentElement;let index=0;
function slide(n){index=(n+slides.length)%slides.length;if(slideParent){slideParent.style.transition='transform .35s';slideParent.style.transform='translateX(-'+index*100+'%)';}$$('button[data-slide-index]').forEach(b=>b.setAttribute('aria-current',String(Number(b.dataset.slideIndex)===index)));}
$$('button[data-slide-index]').forEach(b=>b.addEventListener('click',()=>slide(Number(b.dataset.slideIndex))));
$$('[data-sugar-option]').forEach(b=>b.addEventListener('click',()=>{slide(b.dataset.sugarOption==='product'?0:3);$$('[data-sugar-option]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));
const viewport=$('buybox-gallery .embla__container')?.parentElement;let touchX=0,touchY=0;viewport?.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX;touchY=e.changedTouches[0].clientY;},{passive:true});viewport?.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX,dy=e.changedTouches[0].clientY-touchY;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))slide(index+(dx<0?1:-1));},{passive:true});
const modal=$('[data-nutrition-modal]');let modalOpener=null;function nutrition(open){if(!modal)return;modal.hidden=!open;if(open&&!modal.open){modalOpener=document.activeElement;modal.showModal();}if(!open&&modal.open){modal.close();modalOpener?.focus();}modal.setAttribute('aria-hidden',String(!open));if(open)$('[data-nutrition-close]',modal)?.focus();}
$$('[data-nutrition-open]').forEach(b=>b.addEventListener('click',()=>nutrition(true)));$$('[data-nutrition-close]').forEach(b=>b.addEventListener('click',()=>nutrition(false)));modal?.addEventListener('cancel',e=>{e.preventDefault();nutrition(false);});nutrition(false);
const drawer=$('[data-header-menu-drawer]');function menu(open){if(!drawer)return;drawer.hidden=!open;drawer.dataset.open=String(open);$$('[data-header-menu-open]').forEach(b=>b.setAttribute('aria-expanded',String(open)));if(open)$('a',drawer)?.focus();}
$$('[data-header-menu-open]').forEach(b=>b.addEventListener('click',()=>menu(drawer.hidden)));$$('[data-header-menu-close]').forEach(b=>b.addEventListener('click',()=>menu(false)));document.addEventListener('keydown',e=>{if(e.key==='Escape'){nutrition(false);if(!drawer.hidden){menu(false);$('[data-header-menu-open]')?.focus();}}});
$$('[data-marquee-toggle]').forEach(b=>b.addEventListener('click',()=>{const track=$('[data-marquee-track]',b.closest('marquee-section'));const paused=track.style.animationPlayState!=='paused';track.style.animationPlayState=paused?'paused':'running';b.setAttribute('aria-pressed',String(paused));b.setAttribute('aria-label',paused?'Play announcement animation':'Pause announcement animation');b.textContent=paused?'▶':'Ⅱ';}));
$$('embla-carousel').forEach(carousel=>{const track=$('.embla__container',carousel);if(!track)return;const view=track.parentElement;view.style.overflowX='auto';view.style.scrollSnapType='x mandatory';$$('.embla__slide',track).forEach(s=>s.style.scrollSnapAlign='start');$$('button',carousel).forEach(b=>{const label=b.getAttribute('aria-label')||'';if(/slide/i.test(label))b.addEventListener('click',()=>view.scrollBy({left:(/previous/i.test(label)?-1:1)*(track.firstElementChild.getBoundingClientRect().width+24),behavior:'smooth'}));});});
const offerPopup=$('#offer-popup'),claimForm=$('[data-offer-claim]');
if(offerPopup&&claimForm){let dismissed=false;try{dismissed=sessionStorage.getItem('aerase-offer-seen')==='1';}catch{}function remember(){try{sessionStorage.setItem('aerase-offer-seen','1');}catch{}}
$('.offer-close',offerPopup).addEventListener('click',()=>{offerPopup.close();remember();});offerPopup.addEventListener('cancel',remember);
claimForm.addEventListener('submit',e=>{e.preventDefault();if(!claimForm.reportValidity())return;offerPopup.close();remember();$('[data-purchase-mode="subscription"]').click();$('#offers').scrollIntoView({behavior:'smooth',block:'start'});claimForm.reset();});
if(!dismissed)setTimeout(()=>{if(!document.querySelector('dialog[open]'))offerPopup.showModal();},5000);
}
const ctx=document.modelContext;if(ctx?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(ctx.registerTool({name:'configure_product',description:'Select one, two or three AERASE bottles. This stages a product selection and does not place an order.',inputSchema:{type:'object',properties:{quantity:{type:'integer',enum:[1,2,3]}},required:['quantity'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(![1,2,3].includes(input.quantity))throw new Error('Choose one, two or three bottles.');$('[data-purchase-option][value="'+input.quantity+'"]').click();return{product:config.brandName+' '+config.productName,quantity,checkoutConnected:purchasable(quantity)};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
})();
